const sketch = (p5obj:any) => {
let magicpower: number = p5obj.random(6,9);
//高い数字を引けると複雑な魔方陣ができやすくなる
let iRGB1: number[] = [  p5obj.random(50,255), p5obj.random(50,255), p5obj.random(50,255), p5obj.random(100,200)  ];
let iRGB2: number[] = [  p5obj.random(100,255), p5obj.random(100,255), p5obj.random(100,255), p5obj.random(100,200)  ];

 p5obj.setup = () => 
{
  p5obj.createCanvas( 1000, 1000 );
  p5obj.background(0);
  p5obj.translate(p5obj.width/2,p5obj.height/2);
  drawMagicCircle( 0,0,375,magicpower );
}

//魔法陣を描く再起関数
const drawMagicCircle = (iCenterX: number, iCenterY: number, iRadius: number, iLevel: number) => {
  let randomstrokeWeight: number = iRadius/100*p5obj.random(5) + iRadius/100 ;
  //円の太さを円の半径を参考にしてランダムで決める
  let nextCircleRadius: number = iRadius/p5obj.random(1.1, 1.5);
  //再起した後に描画する円のサイズを決める
  p5obj.stroke( iRGB1[0], iRGB1[1], iRGB1[2] );
  p5obj.strokeWeight(randomstrokeWeight);
  p5obj.fill(0,0,0,100);
  p5obj.circle(iCenterX, iCenterY, 2*iRadius );
  p5obj.noFill();

/*図形の模様を描画する。それぞれ一定の確率で半透明の円に沿ったベアリングのような円、円の原点を中心とした複数個の三角形、謎の線が描画される。*/
  p5obj.push();
  let irandom: number = p5obj.random(1,100);
  let iShapes: number = p5obj.random(3,7);
  let iRotateRadians: number = 360/iShapes;
  p5obj.translate(iCenterX, iCenterY);
  p5obj.stroke( iRGB2[0], iRGB2[1], iRGB2[2] );
  p5obj.strokeWeight(randomstrokeWeight/5+iLevel/5);
  if (irandom < 20 && iLevel > 4 )
  //ベアリングのような円を描画する、中心に近いほど図形的に美しくなくなるのでiLevelが5以上の時のみ確率で描画する。
  {
    for (let iX: number = 0; iX < iShapes; iX ++)
    {
      p5obj.circle(0, (iRadius+nextCircleRadius)/2, iRadius-nextCircleRadius);
      p5obj.circle(0, (iRadius+nextCircleRadius)/2, (iRadius-nextCircleRadius)/1.5);
      p5obj.rotate(p5obj.radians(iRotateRadians));
    }
  }
  else if (irandom < 20 )
  //三角形を複数個描画する。数によって六芒星など様々な形になる。
  {
    for (let iX: number = 0; iX < iShapes; iX ++)
    {
      let iTriangleinCircle: number = iRadius/2;
      p5obj.triangle(0 , 2*iTriangleinCircle ,iTriangleinCircle * p5obj.sqrt(3) ,-iTriangleinCircle ,-iTriangleinCircle * p5obj.sqrt(3) ,-iTriangleinCircle);
      p5obj.rotate(p5obj.radians(iRotateRadians));
    }
  }
  else if (irandom < 50 && iLevel>2 )
  //機械のような謎の線を描画する。
  {
    for (let iX: number = 0; iX < iShapes; iX ++)
    {
      p5obj.line(iRadius ,0 ,(iRadius + nextCircleRadius)/2 ,0 );
      p5obj.arc(0 ,0 ,iRadius + nextCircleRadius ,iRadius + nextCircleRadius ,p5obj.radians(0) ,p5obj.radians(iRotateRadians/2));
      p5obj.push();
      p5obj.rotate(p5obj.radians(iRotateRadians/2));
      p5obj.line((iRadius + nextCircleRadius)/2 ,0 ,nextCircleRadius ,0 );
      p5obj.pop();
      p5obj.rotate(p5obj.radians(iRotateRadians));
    }
  }
  else
  {
  }
  p5obj.pop();
    
/*魔法陣を再起して描画する。*/
  let recursionprobability: number = (p5obj.random(100));

  if( iLevel > 1 )
  //前描いた円より小さい円を描画する
  {
    drawMagicCircle( iCenterX, iCenterY, nextCircleRadius , iLevel - 1 );
  }
  if( 3 < iLevel && iLevel < magicpower )
  //iLevelが５以上の時、描画した円の円周上のどこかに確率で１個または２個の魔法陣を追加して描画する。描画された魔法陣もiLevelが５以上であればさらに再起して描画される。
  {
    if (recursionprobability < 40)
    {
      let irandomradians: number = p5obj.random(360);
      drawMagicCircle( iCenterX + iRadius*p5obj.cos(p5obj.radians(irandomradians)) ,iCenterY + iRadius*p5obj.sin(p5obj.radians(irandomradians))   ,iRadius/p5obj.random(2,4) ,iLevel - 1);
    }
    else if (recursionprobability < 60)
    {
      let irandomradians: number = p5obj.random(360);
      drawMagicCircle( iCenterX + iRadius*p5obj.cos(p5obj.radians(irandomradians)) ,iCenterY + iRadius*p5obj.sin(p5obj.radians(irandomradians))   ,iRadius/p5obj.random(1.4,3) ,iLevel - 1);
      let irandomradians2: number = p5obj.random(360);
      drawMagicCircle( iCenterX + iRadius*p5obj.cos(p5obj.radians(irandomradians2)) ,iCenterY + iRadius*p5obj.sin(p5obj.radians(irandomradians2))   ,iRadius/p5obj.random(1.4,3) ,iLevel - 1);
    }
  }
}

};

export default sketch;
