const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.background(255);

p5obj.stroke(200);
p5obj.blendMode(p5obj.SUBTRACT);

for (var ix=10; ix<500; ix+=40)
{
  for (var iy=10; iy<500; iy+=40)
  {
    p5obj.strokeWeight(20);  //蜀・ｼ磯ｻ偵＞驛ｨ蛻・ｼ峨・髫咎俣

    p5obj.stroke(p5obj.random(0, 100), p5obj.random(0, 120), p5obj.random(0, 80));
    p5obj.circle(ix, iy, 45); //鮟偵＞驛ｨ蛻・
  }
}
p5obj.blendMode(p5obj.SCREEN);

for (var ix=20; ix<500; ix+=40)
{
  for (var iy=20; iy<500; iy+=40)
  {
    p5obj.strokeWeight(1);  //蜀・・髫咎俣

    p5obj.stroke(p5obj.random(50, 255), p5obj.random(50, 255), p5obj.random(50, 255));
    p5obj.line(ix, iy, ix+20, iy+20);
    p5obj.line(ix+20, iy, ix, iy+20);  //繝舌ヤ蜊ｰ
    p5obj.circle(ix+20, iy, 2);
    p5obj.circle(ix, iy+20, 2);
    p5obj.circle(ix+20, iy+20, 2);
    p5obj.circle(ix, iy, 2); //鄂ｰ縺ｮ蜻ｨ繧翫・轤ｹ
  }
}

  };
};

export default sketch;
