const sketch = (p5obj:any) => {
/**
 赤色>時間/黄色>分/青色>秒
ひし形12個が30度ずつ回転する。
菱形1個=1時間単位(時、分、秒)
12*5=60だから5回回転すれば（青）1分、（黄）1時間になる。
1回転ごとに透明度が増す。
*/


let L: number;       
let angle: number;  

p5obj.setup = () => {
  p5obj.createCanvas(1000,1000);
  L=80;         // 一辺の長さ
  angle=p5obj.PI/12 ; // 'angle (= 15度)'を繰り返すので変数に設定
}

p5obj.draw = () => {
  p5obj.background(255); 
  
  //hour
  p5obj.stroke(200 ,0,0,30);    
  p5obj.fill(200,0,0,10);  
  figure(p5obj.width/2,p5obj.height/4,p5obj.hour());        //x,y,hour
  
  //minute
  p5obj.stroke(250,200,0,30);
  p5obj.fill(250,200,0,10);
  figure(3*p5obj.width/4,2*p5obj.height/3,p5obj.minute());  //x,y,minute
  
  //second
  p5obj.stroke(0,0,200,30);
  p5obj.fill(0,0,200,20);
  figure(p5obj.width/4,2*p5obj.height/3,p5obj.second());    //x,y,second
}

const figure = (x: number, y: number, time: number) => {

  p5obj.push();                    // 画面を回転
  p5obj.translate(x,y);                  // (x,y)を原点にする
  for(let i: number = 0; i<time;i++){        // 持ってくる時間ほど繰り返す //１回で30度ずつ移動し12回で１回転
    p5obj.quad(0,0,-L*p5obj.sin(angle),-L*p5obj.cos(angle),0,-2*L*p5obj.cos(angle),L*p5obj.sin(angle),-L*p5obj.cos(angle)); //菱形の下の頂点を原点に設定
    p5obj.rotate(2*angle);         //角度回転(15*2)30度ずつ
  }                          // 毎フレームごと時間だけ描くのでforを使用　// 時間の分繰り返すためi<time
                             //12以上ではfillが１stack
  p5obj.pop();               //画面回転を終わらせる
  
}

};

export default sketch;
