const sketch = (p:any) => {
    p.setup = () => {
p.createCanvas(500, 500);      // Window Size
p.colorMode(p.RGB, 1.0); // RGB(0.0~1.0)
var fR, fG, fB;      // Window RGB
for (var iX=0; iX<p.width; iX++)
{
  for (var iY=0; iY<p.height; iY++)
  {
    /* Example */
    fG = 1*p.tan(100*p.sqrt((p.pow((iX-250), 2)+p.pow((iY-250), 2))));
    fB = 100*p.tan(100*p.sqrt((p.pow((iX-250), 2)+p.pow((iY-250), 2))));
    fR = 0.2*p.tan(100*p.sqrt((p.pow((iX-250), 2)+p.pow((iY-250), 2))));

    // draw pixel
    p.stroke(fR, fG, fB);
    p.point(iX, iY);
  }
}

  };
};

export default sketch;
