const sketch = (p5obj:any) => {


p5obj.setup = () => 
{
  p5obj.createCanvas(400, 800);
  p5obj.colorMode(p5obj.RGB);
  p5obj.background(79, 94, 117);
  p5obj.frameRate(50);
  p5obj.smooth();
}

p5obj.draw = () => 
{
  let s: number = p5obj.second();//秒数
  let m: number = p5obj.minute();//分数
  let h: number = p5obj.hour();//時間
  p5obj.noStroke();

  if (s<59) {
    p5obj.fill(200, 211, 221);
    p5obj.circle( p5obj.random(s*7), p5obj.random(p5obj.height), 0.5 + p5obj.random(2) );
  } else {
    p5obj.fill(79, 94, 117);
    p5obj.rect(0, 0, 400, 1000);
  }
  // 星（左から右へ６０秒かけて増殖、５９秒でリセットのループ）

  p5obj.fill(251, 203, 114);
  p5obj.arc(h*16.7, 200, 100, 100, 200, 300);
  p5obj.fill(79, 94, 117);
  p5obj.circle(h*16.7+30, 180, 100 );//月(24時間かけて左から右へ移動)


  p5obj.stroke(79, 94, 117);

  p5obj.fill(45, 44, 45);
  p5obj.rect(0, 400, 80, 400);
  p5obj.rect(0, 350, 40, 50);
  p5obj.rect(0, 200, 10, 150);
  //一番左のビル

  if (m<=5&& m>=0) {
    p5obj.fill(251, 203, 114);
  } else {
    p5obj.fill(251-p5obj.random(51), 203+p5obj.random(116), 114+p5obj.random(107));
  }
  for (let a: number = 0; a<50; a++)
    p5obj.rect(-10, 430+a*35, 15, 15);//窓１、（5分ごとに窓の明かりが遷移する）

  if (m<=10&& m>5) {
    p5obj.fill(251, 203, 114);
  } else {
    p5obj.fill(251-p5obj.random(51), 203+p5obj.random(116), 114+p5obj.random(107));
  }
  for (let a: number = 0; a<50; a++)
    p5obj.rect(10, 430+a*35, 15, 15);//窓２、１０分目

  if (m<=15&& m>10) {
    p5obj.fill(251, 203, 114);
  } else {
    p5obj.fill(251-p5obj.random(51), 203+p5obj.random(106), 114+p5obj.random(107));
  }
  for (let a: number = 0; a<50; a++)
    p5obj.rect(30, 430+a*35, 15, 15);//窓３、１５分目

  if (m<=20 && m>15) {
    p5obj.fill(251, 203, 114);
  } else {
    p5obj.fill(251-p5obj.random(51), 203+p5obj.random(96), 114+p5obj.random(107));
  }
  for (let a: number = 0; a<50; a++)
    p5obj.rect(50, 430+a*35, 15, 15);
  //窓４、２０分目

  p5obj.fill(45, 44, 45);
  p5obj.rect(80, 500, 20, 500);//隙間

  p5obj.rect(100, 450, 100, 400);//左から２番目のビル

  if (m<=25&& m>20) {
    p5obj.fill(251, 203, 114);
  } else {
    p5obj.fill(251-p5obj.random(51), 203+p5obj.random(86), 114+p5obj.random(107));
  }
  for (let a: number = 0; a<50; a++)
    p5obj.rect(123, 480+a*35, 15, 15);//窓５、２５分目

  if (m<=30&& m>25) {
    p5obj.fill(251, 203, 114);
  } else {
    p5obj.fill(251-p5obj.random(51), 203+p5obj.random(76), 114+p5obj.random(107));
  }
  for (let a: number = 0; a<50; a++)
    p5obj.rect(143, 480+a*35, 15, 15);//窓６、３０分目

  if (m<=35&& m>30) {
    p5obj.fill(251, 203, 114);
  } else {
    p5obj.fill(251-p5obj.random(51), 203+p5obj.random(66), 114+p5obj.random(107));
  }
  for (let a: number = 0; a<50; a++)
    p5obj.rect(163, 480+a*35, 15, 15);
  //窓７、３５分目

  p5obj.fill(45, 44, 45);
  p5obj.rect(200, 600, 25, 300);//隙間

  p5obj.rect(225, 480, 130, 400);//右から２番目のビル
  p5obj.fill(251, 203, 114);

  if (m<=40&& m>35) {
    p5obj.fill(251, 203, 114);
  } else {
    p5obj.fill(251-p5obj.random(51), 203+p5obj.random(56), 114+p5obj.random(107));
  }
  p5obj.rect(245, 500, 10, 400);//窓８、４０分目

  if (m<=45&& m>40) {
    p5obj.fill(251, 203, 114);
  } else {
    p5obj.fill(251-p5obj.random(51), 203+p5obj.random(45), 114+p5obj.random(107));
  }
  p5obj.rect(270, 500, 10, 400);//窓９、４５分目

  if (m<=50&& m>45) {
    p5obj.fill(251, 203, 114);
  } else {
    p5obj.fill(251-p5obj.random(51), 203+p5obj.random(36), 114+p5obj.random(107));
  }
  p5obj.rect(295, 500, 10, 400);//窓１０、５０分目

  if (m<=55&& m>50) {
    p5obj.fill(251, 203, 114);
  } else {
    p5obj.fill(251-p5obj.random(51), 203+p5obj.random(26), 114+p5obj.random(107));
  }
  p5obj.rect(320, 500, 10, 400);
  ;//窓１１、５５分目

  p5obj.fill(45, 44, 45);
  p5obj.rect(355, 350, 100, 450);//一番右のビル

  for (let a: number = 0; a<3; a++) {
    for (let b: number = 0; b<50; b++) {
      if (m<=59 && m>55) {
        p5obj.fill(251, 203, 114);
      } else {
        p5obj.fill(251-p5obj.random(51), 203+p5obj.random(18), 114+p5obj.random(107));
      }
      p5obj.rect(380+20*a, 380+b*40, 30, 15);
    }
  }//窓１２、最後
}

};

export default sketch;
