const sketch = (p5obj:any) => {
    p5obj.setup = () => {
//謨吩ｼ壹・繧ｹ繝・Φ繝峨げ繝ｩ繧ｹ繧偵Δ繝√・繝輔↓縲√Λ繝ｳ繝繝縺ｫ螟牙喧縺吶ｋ濶ｲ魄ｮ繧・°縺ｪ閭梧勹縺ｨ蜈峨・闃ｱ蠑√ｒ陦ｨ迴ｾ縺励◆縲・
p5obj.createCanvas(500, 500);

p5obj.background(0);//閭梧勹繧帝ｻ偵↓

p5obj.blendMode(p5obj.DIFFERENCE);//蟾ｮ縺ｮ邨ｶ蟇ｾ蛟､
for (var iX = 0; iX<170; iX++ )//閭梧勹縺ｮ讓｡讒倥ｄ濶ｲ蠖ｩ繧偵Λ繝ｳ繝繝逕滓・
{

  p5obj.colorMode(p5obj.HSB);//繧ｫ繝ｩ繝ｼ繝｢繝ｼ繝峨ｒHSB縺ｫ
  p5obj.fill(p5obj.random(360), 150, 300);
  p5obj.rect(p5obj.random(500), p5obj.random(500), p5obj.random(1, 300), p5obj.random(1, 200));//繝ｩ繝ｳ繝繝髟ｷ譁ｹ蠖｢
  p5obj.circle(p5obj.random(500), p5obj.random(500), p5obj.random(3, 250));//繝ｩ繝ｳ繝繝蜀・
  p5obj.ellipse(p5obj.random(500), p5obj.random(500), p5obj.random(1, 500), p5obj.random(1, 500));//繝ｩ繝ｳ繝繝讌募・
}

p5obj.translate(250, 250);//蝓ｺ貅悶ｒ荳ｭ蠢・↓
p5obj.noFill();
p5obj.strokeWeight(30);
for (var iLy=0; iLy<500; iLy++)//荳ｭ蠢・°繧画叛蟆・憾縺ｫ莨ｸ縺ｳ繧狗ｽｫ邱・
{
  p5obj.stroke(255);
  p5obj.line(0, iLy, 0, 200);
  p5obj.rotate(p5obj.radians(36));
  p5obj.rotate(p5obj.radians(-18));
  p5obj.strokeWeight(5);
  p5obj.circle(0, 0, 150);//荳ｭ蠢・・縺ｨ螟冶ｼｪ
}

for ( var iCircle = 0; iCircle < 8; iCircle++ )//螟門捉縺ｮ闃ｱ蠑√・繧医≧縺ｪ譖ｲ邱・
{
  p5obj.strokeWeight(9);
  p5obj.stroke(255);
  p5obj.rotate(p5obj.radians(45));
  p5obj.circle(190, 0, 300);
}

  };
};

export default sketch;
